<?php
namespace App\Filament\Resources\Orders;
use App\Filament\Resources\Orders\Pages\{EditOrder,ListOrders}; use App\Models\Order; use BackedEnum; use Filament\Resources\Resource; use Filament\Schemas\Schema; use Filament\Tables\Table; use Filament\Support\Icons\Heroicon; use Filament\Forms\Components\{Select,TextInput,Textarea,Repeater}; use Filament\Tables\Columns\TextColumn;
class OrderResource extends Resource {protected static ?string $model=Order::class;protected static string|BackedEnum|null $navigationIcon=Heroicon::OutlinedShoppingCart;protected static ?string $navigationLabel='Encomendas';protected static string|\UnitEnum|null $navigationGroup='Loja online';public static function form(Schema $s):Schema{return $s->components([TextInput::make('number')->disabled(),Select::make('status')->options(['pending_payment'=>'Aguarda pagamento','processing'=>'Em preparação','shipped'=>'Expedida','completed'=>'Concluída','cancelled'=>'Cancelada','payment_failed'=>'Falha no pagamento'])->required(),Select::make('payment_status')->options(['unpaid'=>'Não pago','paid'=>'Pago','partially_refunded'=>'Reembolso parcial','refunded'=>'Reembolsado','failed'=>'Falhou'])->required(),Select::make('fulfilment_status')->options(['unfulfilled'=>'Por preparar','partial'=>'Parcial','fulfilled'=>'Preparado'])->required(),TextInput::make('customer_name')->disabled(),TextInput::make('email')->disabled(),TextInput::make('total')->prefix('€')->disabled(),Textarea::make('customer_notes')->disabled()->columnSpanFull(),Repeater::make('items')->relationship()->schema([TextInput::make('quantity')->disabled(),TextInput::make('name')->disabled(),TextInput::make('variant_name')->disabled(),TextInput::make('line_total')->prefix('€')->disabled()])->columns(4)->columnSpanFull()]);}public static function table(Table $t):Table{return $t->columns([TextColumn::make('created_at')->dateTime('d/m/Y H:i')->sortable(),TextColumn::make('number')->searchable(),TextColumn::make('customer_name')->searchable(),TextColumn::make('total')->money('EUR'),TextColumn::make('payment_status')->badge(),TextColumn::make('status')->badge()])->recordActions([\Filament\Actions\EditAction::make()]);}public static function getPages():array{return ['index'=>ListOrders::route('/'),'edit'=>EditOrder::route('/{record}/edit')];}}
